MMB-01.code:
// 100 astronaut cards arranged randomly
int find_commander_rahul(AstronautCard cards[100]) {
    for (int i = 0; i < 100; i++) {
        if (is_commander_rahul(cards[i])) {
            return i; // Found Rahul's card
        }
    }
    return -1; // Not found
}

